using System;
using Irihi.Lingua;

namespace KubeUI.Foundation.Localization;

/// <summary>
/// Value access for Lingua resource observables.
/// </summary>
public static class LinguaObservableExtensions
{
    /// <summary>
    /// Returns the value currently published by a Lingua resource observable without creating a subscription.
    /// </summary>
    /// <param name="source">The observable property generated by a <see cref="LinguaManagerAttribute"/> manager.</param>
    /// <returns>The current value, or <see langword="null"/> when no value has been published.</returns>
    /// <exception cref="InvalidCastException">The observable was not produced by a Lingua manager.</exception>
    /// <remarks>
    /// Use only where an observable cannot be bound: structural strings (table column keys, navigation names,
    /// resource-config metadata), one-shot messages, comparisons, and URIs. Live control properties must bind the
    /// observable instead, via <see cref="Avalonia.AvaloniaObjectExtensions.ToBinding{T}(System.IObservable{T})"/>
    /// and a declarative property extension accepting a <see cref="Avalonia.Data.BindingBase"/>.
    /// Every call site of this method is a known non-reactive site; it forms the audit list for culture-change refresh work.
    /// </remarks>
    public static string? CurrentValue(this IObservable<string?> source)
        => ((LinguaObservableString)source).CurrentValue;
}
